package io.github.describeadmin.codegen.parser;

import org.junit.jupiter.api.Test;
import org.yaml.snakeyaml.Yaml;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class SpecLoaderMutaGate2Test {

    private static String spec(String module) {
        return """
                basePackage: com.example.demo
                module: %s
                entity: Project
                table: biz_project
                layout: flat
                fields:
                  - name: projectName
                    type: string
                    length: 64
                """.formatted(module);
    }

    @Test
    void moduleNameValidationFlagsOnlyInvalidModules() {
        // 非法 module（大写开头）必须产生恰好一条 module 错误
        SpecException ex = assertThrows(SpecException.class,
                () -> SpecLoaderBridge.parse(new Yaml().load(spec("Project")), "t.yaml"));
        List<String> moduleErrors = ex.errors().stream()
                .filter(e -> e.contains("module \"Project\""))
                .toList();
        assertEquals(1, moduleErrors.size());

        // 合法 module 不应产生任何错误
        assertEquals("work_order",
                SpecLoaderBridge.parse(new Yaml().load(spec("work_order")), "t.yaml").module());
    }
}

package io.github.describeadmin.codegen.parser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class SpecLoaderMutaGate3Test {

    private static Map<String, Object> spec(String entity) {
        Map<String, Object> field = new HashMap<>();
        field.put("name", "projectName");
        field.put("type", "string");
        field.put("length", 64);

        Map<String, Object> root = new HashMap<>();
        root.put("basePackage", "com.example.demo");
        root.put("module", "project");
        root.put("entity", entity);
        root.put("table", "biz_project");
        root.put("fields", List.of(field));
        root.put("layout", "nested");
        return root;
    }

    @Test
    void entityMustBeUpperCamel() {
        // A valid entity name must not be reported by the UPPER_CAMEL check.
        assertEquals("Project", SpecLoader.parse(spec("Project"), "t.yaml", "nested").entity());

        // A lower-camel entity name must be reported.
        SpecException ex = assertThrows(SpecException.class,
                () -> SpecLoader.parse(spec("project"), "t.yaml", "nested"));
        assertTrue(ex.errors().stream()
                        .anyMatch(e -> e.contains("entity \"project\"") && e.contains("应为大驼峰")),
                "errors: " + ex.errors());
    }
}

package io.github.describeadmin.codegen.parser;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

class SpecLoaderMutaGate4Test {

    private static Map<String, Object> spec(String entity) {
        return Map.of(
                "basePackage", "com.example.demo",
                "module", "project",
                "entity", entity,
                "table", "biz_project",
                "layout", "nested",
                "fields", List.of(Map.of("name", "projectName", "type", "string")));
    }

    @Test
    void entitySuffixIsRejectedAndPlainEntityIsAccepted() {
        // A plain entity name must parse without error.
        assertDoesNotThrow(() -> SpecLoader.parse(spec("Project"), "t.yaml", null));

        // An entity name ending in "Entity" is valid UpperCamel, so only the suffix check can reject it.
        SpecException ex = assertThrows(SpecException.class,
                () -> SpecLoader.parse(spec("ProjectEntity"), "t.yaml", null));
        List<String> errors = ex.errors();
        assertTrue(errors.stream().anyMatch(e -> e.contains("不要带 Entity 后缀")),
                "expected suffix error but got: " + errors);
        assertEquals(1, errors.stream().filter(e -> e.contains("entity \"ProjectEntity\"")).count());
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate5Test {

    private static Map<String, Object> spec(String table) {
        Map<String, Object> field = new LinkedHashMap<>();
        field.put("name", "projectName");
        field.put("type", "string");
        field.put("length", 64);

        Map<String, Object> root = new LinkedHashMap<>();
        root.put("basePackage", "com.example.demo");
        root.put("module", "project");
        root.put("entity", "Project");
        root.put("table", table);
        root.put("fields", List.of(field));
        return root;
    }

    @Test
    void tableNameFormatIsValidatedExactlyWhenInvalid() {
        // a valid snake_case table must not produce any error
        ModuleSpec ok = assertDoesNotThrow(
                () -> SpecLoader.parse(spec("biz_project"), "t.yaml", "nested"));
        assertEquals("biz_project", ok.table());

        // an invalid table name must be reported with the specific message
        SpecException ex = assertThrows(SpecException.class,
                () -> SpecLoader.parse(spec("BizProject"), "t.yaml", "nested"));
        assertEquals(1, ex.errors().size());
        assertTrue(ex.errors().get(0).contains(
                "t.yaml: table \"BizProject\" 应为小写下划线形式，如 biz_project"));
    }
}

package io.github.describeadmin.codegen.parser;

import org.junit.jupiter.api.Test;
import org.yaml.snakeyaml.Yaml;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate6Test {

    @Test
    void emptyFieldsReportedOnlyWhenNoOtherErrors() {
        String header = """
                basePackage: com.example.demo
                module: project
                entity: Project
                table: biz_project
                fields: []
                """;
        SpecException ex = assertThrows(SpecException.class,
                () -> SpecLoaderBridge.parse(new Yaml().load(header), "t.yaml", "nested"));
        assertEquals(1, ex.errors().size());
        assertTrue(ex.errors().get(0).contains("fields 为空"));

        String withOtherError = """
                module: project
                entity: Project
                table: biz_project
                fields: []
                """;
        SpecException ex2 = assertThrows(SpecException.class,
                () -> SpecLoaderBridge.parse(new Yaml().load(withOtherError), "t.yaml", "nested"));
        assertEquals(1, ex2.errors().size());
        assertTrue(ex2.errors().get(0).contains("basePackage"));
        assertTrue(ex2.errors().stream().noneMatch(e -> e.contains("fields 为空")));
    }
}

package io.github.describeadmin.codegen.parser;

import io.github.describeadmin.codegen.model.ModuleSpec;
import org.junit.jupiter.api.Test;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;

class SpecLoaderMutaGate7Test {

    private static Map<String, Object> baseSpec() {
        Map<String, Object> field = new LinkedHashMap<>();
        field.put("name", "projectName");
        field.put("type", "string");
        field.put("length", 128);

        Map<String, Object> root = new LinkedHashMap<>();
        root.put("basePackage", "com.example.demo");
        root.put("module", "project");
        root.put("entity", "Project");
        root.put("table", "biz_project");
        root.put("fields", List.of(field));
        return root;
    }

    @Test
    void commentDefaultsToEntityOnlyWhenAbsent() {
        // comment absent -> falls back to the entity name
        ModuleSpec withoutComment = SpecLoader.parse(baseSpec(), "test.yaml", "nested");
        assertEquals("Project", withoutComment.comment());

        // comment present -> used as is
        Map<String, Object> spec = baseSpec();
        spec.put("comment", "项目管理");
        ModuleSpec withComment = SpecLoader.parse(spec, "test.yaml", "nested");
        assertEquals("项目管理", withComment.comment());
    }
}

package io.github.describeadmin.codegen.parser;

import org.junit.jupiter.api.Test;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class SpecLoaderMutaGate8Test {

    private static Map<String, Object> validRoot() {
        Map<String, Object> field = new LinkedHashMap<>();
        field.put("name", "projectName");
        field.put("type", "string");
        field.put("length", 128);

        Map<String, Object> root = new LinkedHashMap<>();
        root.put("basePackage", "com.example.demo");
        root.put("module", "project");
        root.put("entity", "Project");
        root.put("table", "biz_project");
        root.put("fields", List.of(field));
        return root;
    }

    @Test
    void missingRequiredKeyIsReported() {
        for (String key : List.of("basePackage", "module", "entity", "table")) {
            Map<String, Object> root = validRoot();
            root.remove(key);

            SpecException ex = assertThrows(SpecException.class,
                    () -> SpecLoader.parse(root, "t.yaml", "nested"),
                    "missing " + key);

            assertEquals(1, ex.errors().size(), "missing " + key + ": " + ex.errors());
            String err = ex.errors().get(0);
            assertTrue(err.startsWith("t.yaml: "), err);
            assertTrue(err.contains("缺少必填项 " + key), err);
        }
    }
}

